local AddonName,SAO=...
local Module="pyromancer"
-- Conquest of Azeroth (Project Ascension) - Pyromancer
-- Researched from db.ascension.gg (class=24).
-- Ember (Resource): "Allows you to cast powerful abilities." Stacks 5 times; generated by
-- Draconic Invocation. Its "Modifies" list confirms Blaze, Echo of Nozdormu and Flames of
-- Neltharion all consume/scale off it.
local emberBuff=807533
local blaze=805500
local echoOfNozdormu=802174
local flamesOfNeltharion=801915
local function useEmber()
	SAO:CreateEffect(
		"pyromancer_ember",
		SAO.ALL_PROJECTS,
		emberBuff,
		"aura",
		{
			overlay={texture="genericarc_01",position="Right"},
			buttons={
				{spellID=blaze,useName=true},
				{spellID=echoOfNozdormu,useName=true},
				{spellID=flamesOfNeltharion,useName=true},
			},
		}
	)
end
local function registerClass(self)
	useEmber()
end
SAO.Class["PYROMANCER"]={
	["Register"]=registerClass,
}
